<?phpnamespace app\api\controller;use app\api\model\Flavor as FlavorModel;use app\api\model\Order as OrderModel;use app\api\model\Cart as CartModel;use app\api\model\Table as TableModel;use app\api\model\CouponUser as CouponUserModel;use app\api\model\Setting;use app\api\model\Device;use hema\delivery\Driver as Delivery;use hema\Helper;/** * 订单控制器 */class Order extends Controller{    private $user;    private $error;    /**     * 构造方法     */    public function initialize()    {        parent::initialize();        $this->user = $this->getUserDetail();   // 用户信息    }         /**     * 订单确认-购物车结算	 * $order_mode 点餐模式 10=扫码，20=外卖	 * $pay_mode 支付模式 0未知 1微信支付，2余额，3现金 4支付宝支付	 * $people 就餐人数	 * $coupon_user_id 优惠券ID	 * $message=买家留言	 * $browser 浏览器类型，只有H5才会传递     */    public function cart($order_mode,$pay_mode=0,$table_id='',$people=0,$message='',$flavor='',$coupon_user_id=0,$browser='')    {        // 商品结算信息        $model = new OrderModel;        $order = $model->getCart($order_mode,$this->user_id);        //购物车里是否有数据        if(sizeof($order['goods_list']) > 0){            $order = $this->vip($order,$order_mode);//会员处理            if($order_mode==20){                //外卖订单处理    		    if(!$order = $this->takeout($order)){    		        return $this->renderError($this->error);    		    }    		}    		//获取优惠券列表            $order['coupon_list'] = CouponUserModel::checkCoupon($this->user_id,$order);            if(sizeof($order['coupon_list']) > 0){                //判断用户选择优惠券进行结算                if($coupon_user_id > 0){                    $coupon = CouponUserModel::get($coupon_user_id,['coupon']);                    $order = $coupon->useCoupon($order);//使用优惠券                }            }        }        //扫码下单        $ware_price = 0;//餐具茶水费        if($order_mode==10 and !empty($table_id)){            $table = TableModel::get($table_id);			//如果餐桌状态空闲中才进行验证，否则为加单			if($table['status']['value'] == 10){			    $order['is_order'] = 1;//点单		        $order['table_name'] = $table['table_name'] . '（点单）';			}else{			    $order['is_order'] = 0;//加单		        $order['table_name'] = $table['table_name'] . '（加单）';			}			$value = Setting::getItem('order');			//是否计算餐具茶水费			if($value['is_people'] == 1 and $value['ware_price'] > 0 and $order['is_order'] == 1){			    $ware_price = (int)$people * $value['ware_price'];//按照人头计算茶位费用			}			$order['order_setting'] = $value;        }        $order['ware_price'] = Helper::number2($ware_price);//餐位茶水费        $order['order_pay_price'] = Helper::number2($order['order_pay_price'] + $ware_price);//重新计算支付费用        if (!$this->request->isPost()) {            return $this->renderSuccess($order);        }        //如果是堂食扫码        if($order_mode==10 and !empty($table_id)){    		$order['table_id'] = $table_id;//扫码    		$order['people'] = $people;        }else{           $order['row_no'] = $model::rowNo();//生成取餐吗         }		$order['message'] = $message;		$order['flavor'] = $flavor;		$order['order_mode'] = $order_mode;		$order['user_id'] = $this->user_id;        // 创建订单        if (!$model->add($order,$coupon_user_id)) {			$error = $model->getError() ?: '订单创建失败';			return $this->renderError($error);          }		// 清空购物车		$Card = new CartModel($this->user_id);		$Card->clearAll();		$order = OrderModel::detail($model['order_id']);		//进行支付操作		if($data = $order->userPay($pay_mode,$this->mp,$browser)){            return $this->renderSuccess($data);        }        $error = $order->getError() ?: '支付失败';        return $this->renderError($error);    }        /**     * 获取口味选项     */    public function flavor()    {        $model = new FlavorModel;        $list = $model->getList(false);        return $this->renderSuccess($list);    }        /**     * 呼叫服务员     */    public function spk($mode,$row_no)    {        Device::push($mode,$row_no);        return $this->renderMsg('操作成功');    }        /**     * 会员处理     */     private function vip($order,$order_mode)     {        $user = $this->user;        //如果是会员        if($user['v']['value'] > 0){            $vip = Setting::getItem('vip');            //如果开启会员折扣            $discount = $vip['vip'][$user['v']['value']-1]['discount'];            if($discount > 0){                //计算会员折扣 - 优惠金额                $price = $order['order_pay_price'] * $discount / 100; //折扣后的价格；                $order['vip_price'] = Helper::number2($order['vip_price']+$order['order_pay_price']-$price);//计算会员优惠金额                $order['order_pay_price'] = Helper::number2($price);//优惠后需要支付得金额                //$order['activity_price'] = Helper::number2($order['activity_price']+$price);//计算优惠金额            }            if($vip['vip'][$user['v']['value']-1]['free_delivery'] == 1 and $order_mode==20){                $order['vip_price'] = Helper::number2($order['vip_price']+$order['delivery_price']);                $order['delivery_price'] = Helper::number2(0);//配送费重置为0元                $order['free_delivery'] = true;//开启免配送费            }        }        return $order;     }        /**     * 外卖订单处理     */     private function takeout($order)     {                 $user = $this->user;		if($user['address_default']){		    $order['address'] = $user['address_default'];			//如果免费派送范围大于0			$shop = Setting::getItem('shop');//获取门店参数			//计算距离			if(!empty($shop['coordinate']) and !empty($user['address_default']['location'])){			    $distance = get_distance($shop['coordinate'],$user['address_default']['location']);			    $distance = $distance['value'];			    			    $delivery = Setting::getItem('delivery');//获取配送参数			    if($delivery['delivery_range'] < $distance){					$order['intra_region'] = true; //超出配送距离				}else{				    //如果超出免费区域就计算配送费					if($delivery['free_range'] < $distance){					    //判断是否开启自动配送        				if($delivery['is_delivery'] == 1 AND $delivery['company'] != 'self'){        				    //如第三方配送，同步第三方配送费        				    if($delivery['company'] == 'uu'){                        		$user_location = explode(',',$user['address_default']['location']);//拆分收货人定位经纬度                                $user_location = gcj02_to_bd09($user_location[0],$user_location[1]);//腾讯坐标系转百度坐标系                                $shop_location = explode(',',$shop['coordinate']);//拆分门店定位经纬度                                $shop_location = gcj02_to_bd09($shop_location[0],$shop_location[1]);//腾讯坐标系转百度坐标系                                $post_data = [                                    'storeNo' => $delivery['uu_shop_id'],//是 门店编号                        			'originId' => order_no(),//第三方对接平台订单id                        			'sendType' => 'SEND',//订单小类 SEND:帮我送 BUY:帮我买 TAKE:帮我取 QUEUE:代排队 NEAR_BUY:就近买                        			'toAddress' => $user['address_default']['detail'],//目的地址                        			//'toUserNote' => '',//目的地址具体门牌号(可为空)                        			'toLat' => $user_location['lat'],//目的地坐标纬度，如果无，传0(坐标系为百度地图坐标系)                        			'toLng' => $user_location['lon'],//目的地坐标经度，如果无，传0(坐标系为百度地图坐标系)                        			//'subscribeType' => 'REAL_TIME',//预约类型(默认实时) REAL_TIME:实时订单 PICKUP_TIME:预约取件时间:DELIVERY_TIME:预约送达时间                        			//'subscribeTime' => '',//预约时间时间戳（秒级）                        			'goodsType' => 'FOOD',//物品类型 CAKE:蛋糕 FOOD:美食 KEY:钥匙 PHONE:手机 FILE:文件 FLOWER:鲜花 OTHER:其他                        			'goodsWeight' => 1,//货物重量（单位KG）                        			//'goodsPrice' => 20,//商品保价，价格（1-10000）按照一定费率收取保价费用（单位元）                        			//'onlineFee' => 0,//下单额外支付小费（单位元）                        			//'serviceCode' => 'UUZC',//UU服务编码 UUZC:UU专送服务 UUJJS:UU加急送服务                        		];        				    }        				    if($delivery['company'] == 'dada'){        				        $user_location = explode(',',$user['address_default']['location']);//拆分收货人定位经纬度        		                $shop_location = explode(',',$shop['coordinate']);//拆分门店定位经纬度        		                //$city_code = $dv->getCiytCode($shop['city']);        		                $post_data = [                        			'shop_no' => $delivery['dada_shop_id'],//是 门店编号                        			'origin_id' => order_no(),//是 第三方订单ID                        			//'city_code' => $city_code,//是 订单所在城市的code                        			'cargo_price' => 1,//是 订单金额                        			'is_prepay' => 0,//是否需要垫付 1:是 0:否 (垫付订单金额，非运费)                        			'receiver_name' => $user['address_default']['name'],//是 收货人姓名                        			'receiver_address' => $user['address_default']['detail'],//是 收货人地址                        			'callback' => base_url() . 'api/delivery/dada',//是 回调URL                        			'receiver_lat' => $user_location[0], //否 收货人地址纬度                        			'receiver_lng' => $user_location[1],//否 收货人地址经度                        			'cargo_weight' => 0.1,//是	订单重量（单位：Kg）                        			'receiver_phone' => $user['address_default']['phone'],//收货人手机号                        		];        				    }        				    if($delivery['company'] == 'make'){        				        $post_data = [                        			'fromcoord' => $shop['coordinate'],//起点地址坐标                                    'tocoord' => $user['address_default']['location'],//终点地址坐标                                    'shop_id' => $delivery['make_shop_id'] //店铺ID	                        		];        				    }        				    if($delivery['company'] == 'shansong'){								$user_location = explode(',',$user['address_default']['location']);//拆分收货人定位经纬度								$shop_location = explode(',',$shop['coordinate']);//拆分门店定位经纬							    $post_data = [									'cityName' => $shop['city'],//城市名称									'appointType' => 0,//预约类型Integer	0立即单，1预约单									//'appointmentDate' => '2020-02-02 22:00',//预约时间String 预约取件时间,只支持一个小时以后两天以内									//'deliveryType' => 1,//Integer(1) 1.帮我送 2.帮我取 ；默认为1									'lbsType' => 1,//坐标类型 0：百度坐标系，1：国测局标准坐标系，默认为0									'storeId' => $delivery['shansong_shop_id'],//店铺ID，长整类型									'sender' => [//寄件人信息										'fromAddress' => $shop['district'],//寄件地址										'fromAddressDetail' =>  $shop['address'],//寄件详细地址											'fromSenderName' =>	$shop['shop_name'],       //寄件人姓名											'fromMobile' =>	$shop['phone'],//寄件人电话，支持11位手机号;支持座机号(格式：010-12345678)										'fromLatitude' => $shop_location[0],//寄件纬度,只支持百度坐标系										'fromLongitude' => $shop_location[1]//寄件经度,只支持百度坐标系									],									'receiverList' => [//收件人信息										'orderNo' => order_no(),	//第三方平台流水号											'toAddress' => $user['address_default']['district'],//收件地址											'toAddressDetail' => $user['address_default']['detail'],//收件详细地址										'toLatitude' => $user_location[0],//收件纬度,只支持百度坐标系										'toLongitude' => $user_location[1],//收件经度,只支持百度坐标系										'toReceiverName' => $user['address_default']['name'],//收件人姓名											'toMobile' => $user['address_default']['phone'],//收件联系人,支持11位手机号；支持座机号格式：010-12345678										'goodType' => 6,//	物品类型,6=餐饮										'weight' =>1 //物品重量，单位为kg									]								];							}        				    if($delivery['company'] == 'sf'){        				        $user_location = explode(',',$user['address_default']['location']);//拆分收货人定位经纬度        		                $shop_location = explode(',',$shop['coordinate']);//拆分门店定位经纬度                        		$post_data = [                        			'shop_id' => $delivery['sf_shop_id'],//$this->shop_id,//店铺ID                        			'shop_type' => 1,//店铺ID类型	1:顺丰店铺ID 2:接入方店铺ID                        			'user_lng' => $user_location[1],//用户地址经度                        			'user_lat' => $user_location[0],//用户地址纬度                        			'user_address' => $user['address_default']['district'].','.$user['address_default']['detail'],//用户详细地址                        			'city_name' => $user['address_default']['city'],//发单城市                        			'weight' => 0,//物品重量（单位：克）                        			'product_type' => 1, //物品类型，测试店铺请填写1，否则会造成【没有匹配的计价规则或计价规则已失效】                        			'is_appoint' => 0,//是否是预约单0：非预约单；1：预约单                        			'expect_time' => time()+1800,//期望送达时间,预约单需必传	秒级时间戳                        			//'expect_pickup_time' => time()+600,//期望取货时间                        			'lbs_type' => 2,//坐标类型，1：百度坐标，2：高德坐标                        			'is_insured' => 0,//是否保价，0：非保价；1：保价                        			'is_person_direct' => 0,//是否是专人直送订单，0：否；1：是                        			'declared_value' => 0,//保价金额，单位：分                        			'gratuity_fee' => 0,//订单小费，不传或者传0为不加小费	单位分，加小费最低不能少于100分                        			'rider_pick_method' => 1,//物流流向	1：从门店取件送至用户 2：从用户取件送至门店                        			'return_flag' => 511,//1:商品总价格，2:配送距离，4:物品重量，8:起送时间，16:期望送达时间，32:支付费用，64:实际支持金额，128:优惠卷总金额，256:结算方式,例如全部返回为填入511                        			'push_time' => time(),                        			//发货店铺信息；Obj,平台级开发者需要传入                        			'shop' => [                        				'shop_name' => $shop['shop_name'],//店铺名称                        				'shop_phone' => $shop['phone'],//店铺电话                        				'shop_address' => $shop['address'],//店铺地址                        				'shop_lng' => $shop_location[1],//店铺经度                        				'shop_lat' => $shop_location[0]//店铺纬度		                        			]                        		];        				    }        				    if($delivery['company'] == 'hmpt'){                        		$post_data = [                                   'shop_id' => $delivery['hmpt_shop_id'],//（必填）门店ID                                    'address' => [                                        'user_name' => $user['address_default']['name'],//（必填）收货人姓名                                        'user_gender' => $user['address_default']['gender']['value'],//（必填）性别,默认0=未知 1=先生 2=女士                                        'user_phone' => $user['address_default']['phone'],//（必填）手机号码                                        'user_lat_lng' => $user['address_default']['location'],//（必填）未知坐标                                        'user_city' => $user['address_default']['city'],//（必填）城市                                        'user_district' => $user['address_default']['district'],//（必填）区县                                        'user_address' => $user['address_default']['detail'],//（必填）详细地址(小区门牌)                                      ]                                ];        				    }        				    $dv = new Delivery($delivery['company']);                    		if($result = $dv->preOrder($post_data)){                    		    $order['delivery_price'] = Helper::number2($result['delivery_price']);//第三方配送费                            }else{                                $this->error = $dv->getError();                                return false;                            }        				}else{    						$order['delivery_price'] = Helper::number2($delivery['delivery_price']);    				    }    				    $order['order_pay_price'] = Helper::number2($order['order_pay_price'] + $order['delivery_price']);					}				}			}		}		return $order;     }}